import struct
import unittest
from lte_timing import adjustments, initial


def dl(command=31, tag=0, length=1):
    return (struct.pack('<B3sHBB', 50, b'\0'*3, 1, 0, 0) +
            struct.pack('<IIIBBH', 1, 0, 123 | (4 << 10), 0x30, 1, 0) +
            (1 | (29 << 1) | (length << 7)).to_bytes(3, 'little') +
            bytes([command | tag << 6]) + b'\0'*8)


class LteTimingTests(unittest.TestCase):
    def test_relative_ce_fields(self):
        row = adjustments(dl(30, 2))[0]
        self.assertEqual((row['delta_steps'], row['tag_id'], row['sfn'], row['subframe']), (-1, 2, 123, 4))
        self.assertIsNone(row['absolute_range_m'])
        self.assertIsNone(row['subscription'])

    def test_malformed_entire_packet_rejected(self):
        for value in (dl()[:-1], dl()+b'\0', dl(length=2), b'\0', dl().replace(b'\x32', b'\x33', 1)):
            self.assertEqual(adjustments(value), [])

    def test_synthetic_rach_success_and_failure(self):
        payload = bytearray(51)
        payload[:6] = bytes([1, 0, 1, 0, 0, 7])
        struct.pack_into('<HBHH', payload, 13, 0, 0, 123, 18)
        body = b'\x01\x01\0\0' + struct.pack('<BBH', 6, 50, 51) + payload
        row = initial(body)[0]
        self.assertEqual(row['ta_index_candidate'], 18)
        self.assertIsNone(row['absolute_range_m'])
        self.assertIsNone(row['subscription'])
        self.assertEqual(initial(body[:-1]), [])
        bad = bytearray(body)
        bad[11] = 1  # unsuccessful overall RACH
        self.assertEqual(initial(bad), [])

    def test_real_capture_relative_events(self):
        rows = adjustments(REAL_CAPTURE)
        self.assertTrue(rows)
        self.assertEqual(rows[0]['ta_command'], 31)
        self.assertEqual(rows[0]['carrier_index'], 0)
        self.assertEqual(rows[0]['tag_id'], 0)


# Real radio-only B063 v50 packet; no IP/user payload.
REAL_CAPTURE = bytes.fromhex('')

if __name__ == '__main__':
    unittest.main()
